1	// Windcave RESTful API Integration
2	import crypto from "crypto";
3	
4	const WINDCAVE_ENDPOINT = process.env.WINDCAVE_ENDPOINT || "https://uat.windcave.com/api/v1";
5	const SESSION_URL = `${WINDCAVE_ENDPOINT}/sessions`;
6	const TRANSACTION_URL = `${WINDCAVE_ENDPOINT}/transactions`;
7	const REQUEST_TIMEOUT = 15000;
8	const RETRY_LIMIT = 5;
9	
10	export function getWindcaveEnv(): "uat" | "sec" {
11	  const endpoint = process.env.WINDCAVE_ENDPOINT || "";
12	  return endpoint.includes("sec.windcave.com") ? "sec" : "uat";
13	}
14	
15	function logAudit(action: string, details: Record<string, any>) {
16	  const sanitized = { ...details };
17	  if (sanitized.apiKey) sanitized.apiKey = "***";
18	  if (sanitized.authorization) sanitized.authorization = "***";
19	  console.log(`[WINDCAVE] [${new Date().toISOString()}] ${action}:`, JSON.stringify(sanitized));
20	}
21	
22	function buildAuthHeader(): string {
23	  const username = process.env.WINDCAVE_USERNAME || "";
24	  const apiKey = process.env.WINDCAVE_API_KEY || "";
25	  return `Basic ${Buffer.from(`${username}:${apiKey}`).toString("base64")}`;
26	}
27	
28	async function fetchWithTimeout(url: string, options: RequestInit): Promise<Response> {
29	  const controller = new AbortController();
30	  const id = setTimeout(() => controller.abort(), REQUEST_TIMEOUT);
31	  try {
32	    return await fetch(url, { ...options, signal: controller.signal });
33	  } finally {
34	    clearTimeout(id);
35	  }
36	}
