38	export interface CreateSessionResult {
39	  success: boolean;
40	  // Legacy HPP URL (kept for backward compatibility)
41	  hppUrl?: string;
42	  // Hosted Fields — card form AJAX submission URL
43	  ajaxSubmitCardUrl?: string;
44	  // Apple Pay JS wrapper AJAX submission URL
45	  ajaxSubmitApplePayUrl?: string;
46	  // Google Pay AJAX submission URL
47	  ajaxSubmitGooglePayUrl?: string;
48	  sessionId?: string;
49	  alreadyComplete?: boolean;
50	  approved?: boolean;
51	  windcaveTransactionId?: string;
52	  error?: string;
53	}
54	
55	export interface QuerySessionResult {
56	  success: boolean;
57	  approved?: boolean;
58	  windcaveTransactionId?: string;
59	  error?: string;
60	}
61	
62	export interface RefundResult {
63	  success: boolean;
64	  refundTransactionId?: string;
65	  error?: string;
66	}
