68	// Create a Windcave payment session — returns all available submission URLs
69	export async function createWindcaveSession(
70	  xId: string,
71	  amount: string,
72	  merchantReference: string,
73	  customerEmail: string,
74	  baseUrl: string,
75	  transactionId: number,
76	  retries = 0,
77	  // Optional override for non-retail flows (e.g. property rent checkout) that need
78	  // their own callback/notification routes. callbackBase must already contain a `?`
79	  // query string so `&result=...` can be appended.
80	  callbacks?: { callbackBase: string; notificationUrl: string }
81	): Promise<CreateSessionResult> {
82	  const callbackBase = callbacks?.callbackBase ?? `${baseUrl}/api/windcave/callback?transactionId=${transactionId}`;
83	  const notificationUrl = callbacks?.notificationUrl ?? `${baseUrl}/api/windcave/notification`;
84	  const body = {
85	    type: "purchase",
86	    amount,
87	    currency: "NZD",
88	    merchantReference,
89	    customer: {
90	      email: customerEmail,
91	    },
92	    callbackUrls: {
93	      approved: `${callbackBase}&result=approved`,
94	      declined: `${callbackBase}&result=declined`,
95	      cancelled: `${callbackBase}&result=cancelled`,
96	    },
97	    notificationUrl,
98	  };
99	
100	  logAudit("CREATE_SESSION_REQUEST", { xId, merchantReference, amount, retries });
101	
102	  let response: Response;
103	  try {
104	    response = await fetchWithTimeout(SESSION_URL, {
105	      method: "POST",
106	      headers: {
107	        "Content-Type": "application/json",
108	        Authorization: buildAuthHeader(),
109	        "X-ID": xId,
110	      },
111	      body: JSON.stringify(body),
112	    });
113	  } catch (err: any) {
114	    const isTimeout = err.name === "AbortError";
115	    logAudit("CREATE_SESSION_NETWORK_ERROR", { xId, error: err.message, isTimeout });
116	    if (retries < RETRY_LIMIT) {
117	      await delay(5000);
118	      return createWindcaveSession(xId, amount, merchantReference, customerEmail, baseUrl, transactionId, retries + 1, callbacks);
119	    }
120	    return { success: false, error: err.message };
121	  }
122	
123	  if (response.status === 200) {
124	    // Duplicate X-ID — session already complete
125	    const data = await response.json();
126	    const tx = data.transactions?.[0];
127	    const approved = tx?.authorised === true;
128	    logAudit("CREATE_SESSION_DUPLICATE_XID", { xId, approved, txId: tx?.id });
129	    return {
130	      success: true,
131	      sessionId: data.id,
132	      alreadyComplete: true,
133	      approved,
134	      windcaveTransactionId: approved ? tx?.id : undefined,
135	    };
136	  }
137	
138	  if (response.status === 202) {
139	    const data = await response.json();
140	    const links: any[] = data.links || [];
141	
142	    const findHref = (rel: string) =>
143	      links.find((l) => l.rel === rel)?.href;
144	
145	    const hppUrl = findHref("hpp") || links.find((l) => l.method === "REDIRECT")?.href;
146	    const ajaxSubmitCardUrl = findHref("ajaxSubmitCard");
147	    const ajaxSubmitApplePayUrl = findHref("ajaxSubmitApplePay");
148	    const ajaxSubmitGooglePayUrl = findHref("ajaxSubmitGooglePay");
149	
150	    logAudit("CREATE_SESSION_PENDING", {
151	      xId,
152	      sessionId: data.id,
153	      hppUrl,
154	      ajaxSubmitCardUrl: !!ajaxSubmitCardUrl,
155	      ajaxSubmitApplePayUrl: !!ajaxSubmitApplePayUrl,
156	      ajaxSubmitGooglePayUrl: !!ajaxSubmitGooglePayUrl,
157	    });
158	
159	    return {
160	      success: true,
161	      sessionId: data.id,
162	      hppUrl,
163	      ajaxSubmitCardUrl,
164	      ajaxSubmitApplePayUrl,
165	      ajaxSubmitGooglePayUrl,
166	      alreadyComplete: false,
167	    };
168	  }
169	
170	  if (response.status >= 400 && response.status < 500) {
171	    const errorBody = await response.text().catch(() => "");
172	    logAudit("CREATE_SESSION_4XX", { xId, status: response.status, errorBody });
173	    return { success: false, error: `Windcave ${response.status}: ${errorBody}` };
174	  }
175	
176	  if (response.status >= 500) {
177	    logAudit("CREATE_SESSION_5XX", { xId, status: response.status, retries });
178	    if (retries < RETRY_LIMIT) {
179	      await delay(5000);
180	      return createWindcaveSession(xId, amount, merchantReference, customerEmail, baseUrl, transactionId, retries + 1, callbacks);
181	    }
182	    return { success: false, error: `Windcave server error ${response.status}` };
183	  }
184	
185	  return { success: false, error: `Unexpected status ${response.status}` };
186	}
187	
188	// Query a session to determine the payment outcome
189	export async function queryWindcaveSession(
190	  sessionId: string,
191	  retries = 0
192	): Promise<QuerySessionResult> {
193	  logAudit("QUERY_SESSION", { sessionId, retries });
194	
195	  let response: Response;
196	  try {
197	    response = await fetchWithTimeout(`${SESSION_URL}/${sessionId}`, {
198	      method: "GET",
199	      headers: { Authorization: buildAuthHeader() },
200	    });
201	  } catch (err: any) {
202	    logAudit("QUERY_SESSION_NETWORK_ERROR", { sessionId, error: err.message });
203	    if (retries < RETRY_LIMIT) {
204	      await delay(5000);
205	      return queryWindcaveSession(sessionId, retries + 1);
206	    }
207	    return { success: false, error: err.message };
208	  }
209	
210	  if (response.status === 200) {
211	    const data = await response.json();
212	    const tx = data.transactions?.[0];
213	    const approved = tx?.authorised === true;
214	    logAudit("QUERY_SESSION_RESULT", { sessionId, approved, txId: tx?.id });
215	    return {
216	      success: true,
217	      approved,
218	      windcaveTransactionId: approved ? tx?.id : undefined,
219	    };
220	  }
221	
222	  if (response.status === 202) {
223	    if (retries < RETRY_LIMIT) {
224	      await delay(5000);
225	      return queryWindcaveSession(sessionId, retries + 1);
226	    }
227	    return { success: false, error: "Session still processing after max retries" };
228	  }
229	
230	  if (response.status >= 400 && response.status < 500) {
231	    const errorBody = await response.text().catch(() => "");
232	    logAudit("QUERY_SESSION_4XX", { sessionId, status: response.status, errorBody });
233	    return { success: false, error: `Windcave ${response.status}: ${errorBody}` };
234	  }
235	
236	  if (response.status >= 500) {
237	    if (retries < RETRY_LIMIT) {
238	      await delay(5000);
239	      return queryWindcaveSession(sessionId, retries + 1);
240	    }
241	    return { success: false, error: `Windcave server error ${response.status}` };
242	  }
243	
244	  return { success: false, error: `Unexpected status ${response.status}` };
245	}
