247	// Submit a Google Pay token to Windcave's ajaxSubmitGooglePay endpoint
248	export async function submitGooglePayToken(
249	  ajaxSubmitGooglePayUrl: string,
250	  googlePayToken: object
251	): Promise<{ success: boolean; approved?: boolean; windcaveTransactionId?: string; error?: string }> {
252	  logAudit("GOOGLEPAY_SUBMIT", { url: ajaxSubmitGooglePayUrl });
253	  try {
254	    // Body format confirmed from Windcave's official SDK source:
255	    // windcavepayments-googlepay-v1.js → __submitTransaction():
256	    //   var tokenObject = { googlePay: JSON.parse(payment.paymentMethodData.tokenizationData.token) };
257	    //   var token = JSON.stringify(tokenObject);
258	    //   self.__ajaxPost(url, token, { "Content-Type": "application/json", "x-seamless": 1 })
259	    // Authorization header must NOT be sent — MHPP AJAX URLs authenticate via unique opaque URL.
260	    const response = await fetchWithTimeout(ajaxSubmitGooglePayUrl, {
261	      method: "POST",
262	      headers: {
263	        "Content-Type": "application/json",
264	        "x-seamless": "1",
265	      },
266	      body: JSON.stringify({ googlePay: googlePayToken }),
267	    });
268	
269	    const text = await response.text();
270	    logAudit("GOOGLEPAY_RESPONSE", { status: response.status, body: text });
271	
272	    if (response.ok) {
273	      let data: any = {};
274	      try { data = JSON.parse(text); } catch {}
275	
276	      // Windcave returns { links: [{ rel: "done"|"3DSecure", href: "..." }] }
277	      if (data.links && Array.isArray(data.links) && data.links.length > 0) {
278	        const link = data.links[0];
279	        logAudit("GOOGLEPAY_LINK", { rel: link.rel, href: link.href?.slice(0, 200) });
280	
281	        if (link.rel === "done") {
282	          // href is our callback URL — result is embedded in the query string
283	          const approved = typeof link.href === "string" && link.href.includes("result=approved");
284	          return { success: true, approved };
285	        }
286	
287	        if (link.rel === "3DSecure") {
288	          // 3DS not supported in server-side submission — log and fall back to session query
289	          logAudit("GOOGLEPAY_3DS_REQUIRED", { href: link.href?.slice(0, 200) });
290	          return { success: false, error: "3DS_REQUIRED" };
291	        }
292	      }
293	
294	      // Fallback: try legacy response fields
295	      const approved = data.authorised === true || data.approved === true || data.responseCode === "00";
296	      return { success: true, approved, windcaveTransactionId: data.id || data.transactionId };
297	    }
298	
299	    logAudit("GOOGLEPAY_ERROR_BODY", { status: response.status, body: text });
300	    return { success: false, error: `Windcave GooglePay ${response.status}: ${text}` };
301	  } catch (err: any) {
302	    logAudit("GOOGLEPAY_ERROR", { error: err.message });
303	    return { success: false, error: err.message };
304	  }
305	}
