307	// Process a refund against an approved transaction
308	export async function createWindcaveRefund(
309	  originalTransactionId: string,
310	  amount: string,
311	  merchantReference: string
312	): Promise<RefundResult> {
313	  const xId = crypto.randomBytes(8).toString("hex");
314	  logAudit("REFUND_REQUEST", { originalTransactionId, amount, merchantReference });
315	
316	  const body = {
317	    type: "refund",
318	    amount,
319	    currency: "NZD",
320	    merchantReference,
321	    transaction2Id: originalTransactionId,
322	  };
323	
324	  try {
325	    const response = await fetchWithTimeout(TRANSACTION_URL, {
326	      method: "POST",
327	      headers: {
328	        "Content-Type": "application/json",
329	        Authorization: buildAuthHeader(),
330	        "X-ID": xId,
331	      },
332	      body: JSON.stringify(body),
333	    });
334	
335	    if (response.ok) {
336	      const data = await response.json();
337	      logAudit("REFUND_SUCCESS", { refundTxId: data.id });
338	      return { success: true, refundTransactionId: data.id };
339	    }
340	
341	    const errorBody = await response.text().catch(() => "");
342	    logAudit("REFUND_FAILED", { status: response.status, errorBody });
343	    return { success: false, error: `Refund failed: ${response.status} ${errorBody}` };
344	  } catch (err: any) {
345	    logAudit("REFUND_ERROR", { error: err.message });
346	    return { success: false, error: err.message };
347	  }
348	}
