350	export function isWindcaveConfigured(): boolean {
351	  return !!(process.env.WINDCAVE_USERNAME && process.env.WINDCAVE_API_KEY);
352	}
353	
354	function delay(ms: number): Promise<void> {
355	  return new Promise((resolve) => setTimeout(resolve, ms));
356	}
