358	// ── Simulation mode (used when credentials are not set) ──────────────────────
359	
360	export function simulateCreateSession(merchantReference: string, baseUrl: string): CreateSessionResult {
361	  const sessionId = `sim_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
362	  logAudit("SIMULATE_SESSION", { sessionId, merchantReference });
363	  const hppUrl = `${baseUrl}/api/windcave/callback?result=approved&sessionid=${sessionId}&sim=1`;
364	  return {
365	    success: true,
366	    sessionId,
367	    hppUrl,
368	    // Fake AJAX submit URLs — the checkout page will detect sim mode and handle accordingly
369	    ajaxSubmitCardUrl: `${baseUrl}/api/windcave/sim-submit?sessionId=${sessionId}&method=card`,
370	    ajaxSubmitApplePayUrl: `${baseUrl}/api/windcave/sim-submit?sessionId=${sessionId}&method=applepay`,
371	    ajaxSubmitGooglePayUrl: `${baseUrl}/api/windcave/sim-submit?sessionId=${sessionId}&method=googlepay`,
372	    alreadyComplete: false,
373	  };
374	}
