377	// the rent callback (/api/checkout/callback) instead of the retail one.
378	export function simulateRentSession(token: string, baseUrl: string): CreateSessionResult {
379	  const sessionId = `sim_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
380	  logAudit("SIMULATE_RENT_SESSION", { sessionId, token });
