389	export function simulateQuerySession(sessionId: string): QuerySessionResult {
390	  const approved = !sessionId.includes("decline");
391	  return {
392	    success: true,
393	    approved,
394	    windcaveTransactionId: approved ? `SIMTXN_${Date.now()}` : undefined,
