398	// ── Attended (Tap to Pay on iPhone) ──────────────────────────────────────────
399	
400	export interface AttendedSessionResult {
401	  success: boolean;
402	  sessionId?: string;
403	  error?: string;
404	}
405	
406	export interface AttendedPaymentResult {
407	  success: boolean;
408	  approved?: boolean;
409	  windcaveTransactionId?: string;
410	  error?: string;
411	}
412	
413	/**
414	 * Step 1 (server-side): Create a Windcave attended session for Tap to Pay on iPhone.
415	 *
416	 * Flow ordering: the iOS SDK (WCPaymentSDK) has already captured the NFC card
417	 * data and returned a token to the JS bridge. This session is then created
418	 * server-side to provide a Windcave context for submitting that token.
419	 *
420	 * Windcave attended sessions use `type: "purchase"` with `attended: true` and
421	 * no callback URLs — the authorisation result is returned synchronously when
422	 * the token is submitted via submitTapToPayToken().
423	 */
424	export async function createAttendedSession(
425	  amount: string,
426	  merchantReference: string,
427	  retries = 0
428	): Promise<AttendedSessionResult> {
429	  const xId = crypto.randomBytes(8).toString("hex");
430	  logAudit("ATTENDED_SESSION_CREATE", { merchantReference, amount, xId, retries });
431	
432	  const body = {
433	    type: "purchase",
434	    amount,
435	    currency: "NZD",
436	    merchantReference,
437	    attended: true,
438	  };
439	
440	  let response: Response;
441	  try {
442	    response = await fetchWithTimeout(SESSION_URL, {
443	      method: "POST",
444	      headers: {
445	        "Content-Type": "application/json",
446	        Authorization: buildAuthHeader(),
447	        "X-ID": xId,
448	      },
449	      body: JSON.stringify(body),
450	    });
451	  } catch (err: any) {
452	    logAudit("ATTENDED_SESSION_NETWORK_ERROR", { xId, error: err.message });
453	    if (retries < RETRY_LIMIT) {
454	      await delay(5000);
455	      return createAttendedSession(amount, merchantReference, retries + 1);
456	    }
457	    return { success: false, error: err.message };
458	  }
459	
460	  const text = await response.text();
461	  logAudit("ATTENDED_SESSION_RESPONSE", { status: response.status, body: text.slice(0, 400) });
462	
463	  if (response.status === 200 || response.status === 202) {
464	    let data: any = {};
465	    try { data = JSON.parse(text); } catch {}
466	    if (data.id) {
467	      return { success: true, sessionId: data.id };
468	    }
469	  }
470	
471	  if (response.status >= 500 && retries < RETRY_LIMIT) {
472	    await delay(5000);
473	    return createAttendedSession(amount, merchantReference, retries + 1);
474	  }
475	
476	  return { success: false, error: `Windcave ${response.status}: ${text.slice(0, 200)}` };
477	}
478	
479	/**
480	 * Step 2: Submit the NFC payment token captured by the Windcave iOS SDK
481	 * (WCPaymentSDK.startTapToPaySession) against an existing attended session.
482	 *
483	 * The token is submitted to Windcave's transactions endpoint. Windcave
484	 * evaluates the contactless card data and returns an authorisation decision.
485	 */
486	export async function submitTapToPayToken(
487	  sessionId: string,
488	  windcaveToken: string,
489	  retries = 0
490	): Promise<AttendedPaymentResult> {
491	  const xId = crypto.randomBytes(8).toString("hex");
492	  logAudit("TAP_TO_PAY_SUBMIT", { sessionId, xId, retries });
493	
494	  const body = {
495	    type: "purchase",
496	    sessionId,
497	    method: "contactless",
498	    token: windcaveToken,
499	  };
500	
501	  let response: Response;
502	  try {
503	    response = await fetchWithTimeout(TRANSACTION_URL, {
504	      method: "POST",
505	      headers: {
506	        "Content-Type": "application/json",
507	        Authorization: buildAuthHeader(),
508	        "X-ID": xId,
509	      },
510	      body: JSON.stringify(body),
511	    });
512	  } catch (err: any) {
513	    logAudit("TAP_TO_PAY_NETWORK_ERROR", { xId, error: err.message });
514	    if (retries < RETRY_LIMIT) {
515	      await delay(5000);
516	      return submitTapToPayToken(sessionId, windcaveToken, retries + 1);
517	    }
518	    return { success: false, error: err.message };
519	  }
520	
521	  const text = await response.text();
522	  logAudit("TAP_TO_PAY_RESPONSE", { status: response.status, body: text.slice(0, 400) });
523	
524	  if (response.ok) {
525	    let data: any = {};
526	    try { data = JSON.parse(text); } catch {}
527	    const approved = data.authorised === true || data.approved === true || data.responseCode === "00";
528	    return { success: true, approved, windcaveTransactionId: data.id || data.transactionId };
529	  }
530	
531	  if (response.status >= 500 && retries < RETRY_LIMIT) {
532	    await delay(5000);
533	    return submitTapToPayToken(sessionId, windcaveToken, retries + 1);
534	  }
535	
536	  return { success: false, error: `Windcave ${response.status}: ${text.slice(0, 200)}` };
537	}
538	
539	/**
540	 * Simulation-only helper — only called when Windcave credentials are NOT configured.
541	 * Never used in production (isWindcaveConfigured() guards all real paths).
542	 */
543	export function simulateAttendedTapToPay(merchantReference: string): AttendedPaymentResult {
544	  const approved = !merchantReference.includes("decline");
545	  logAudit("SIMULATE_TAP_TO_PAY", { merchantReference, approved });
546	  return {
547	    success: true,
548	    approved,
549	    windcaveTransactionId: approved ? `SIMTXN_TTP_${Date.now()}` : undefined,
550	  };
551	}
552	
553	// Legacy service wrapper kept for backward compatibility with NFC routes
554	export class WindcaveService {
555	  isConfigured(): boolean {
556	    return isWindcaveConfigured();
557	  }
558	}
559	
560	export const windcaveService = new WindcaveService();
