1098	  // Tap to Pay (Windcave attended / Tap to Pay on iPhone)
1099	  // Required: {merchantId, amount, windcaveToken (when Windcave is configured)}
1100	  // Optional: {transactionId} — ID of the pending transaction to finalize; if omitted, uses the
1101	  //   merchant's current active pending transaction. Amount is always taken from the pending
1102	  //   transaction's stored price to guarantee ledger/processor consistency.
1103	  // "Paywave" is the NZ contactless payment brand used in the UI; the underlying protocol is
1104	  //   Windcave's attended Tap to Pay on iPhone (WCPaymentSDK + server-side session flow).
1105	  app.post("/api/transactions/tap-to-pay", authenticateToken, async (req: AuthenticatedRequest, res) => {
1106	    try {
1107	      const { merchantId, transactionId, amount, windcaveToken } = req.body;
1108	
1109	      if (!merchantId || !amount) {
1110	        return res.status(400).json({ message: "merchantId and amount are required" });
1111	      }
1112	      const mid = parseInt(merchantId);
1113	      if (!checkMerchantOwnership(req, mid)) {
1114	        return res.status(403).json({ message: "Access denied" });
1115	      }
1116	
1117	      const requestedAmount = parseFloat(amount);
1118	      if (isNaN(requestedAmount) || requestedAmount <= 0) {
1119	        return res.status(400).json({ message: "Invalid amount" });
1120	      }
1121	
1122	      // Resolve the pending transaction to finalize.
1123	      // Prefer the explicitly supplied transactionId, otherwise use the merchant's active pending one.
1124	      let pendingTransaction: Awaited<ReturnType<typeof storage.getTransaction>> | undefined;
1125	      if (transactionId) {
1126	        pendingTransaction = await storage.getTransaction(parseInt(transactionId));
1127	        if (!pendingTransaction || pendingTransaction.merchantId !== mid) {
1128	          return res.status(404).json({ message: "Transaction not found" });
1129	        }
1130	        if (pendingTransaction.status !== "pending") {
1131	          return res.status(409).json({ message: "Transaction is no longer pending" });
1132	        }
1133	      } else {
1134	        pendingTransaction = await storage.getActiveTransactionByMerchant(mid);
1135	      }
1136	
1137	      // The amount to charge Windcave is always the pending transaction's stored price.
1138	      // If no pending transaction, fall back to request body amount.
1139	      // This prevents any divergence between charged amount and recorded ledger amount.
1140	      const chargeAmount = pendingTransaction
1141	        ? parseFloat(pendingTransaction.price)
1142	        : requestedAmount;
1143	
1144	      if (isNaN(chargeAmount) || chargeAmount <= 0) {
1145	        return res.status(400).json({ message: "Invalid charge amount" });
1146	      }
1147	
1148	      const merchantRef = `TAPTP-${pendingTransaction?.id ?? Date.now()}`;
1149	      let paymentResult;
1150	
1151	      if (isWindcaveConfigured()) {
1152	        // Require a real NFC token when Windcave credentials are configured.
1153	        // Fail closed — never simulate a payment when credentials are present.
1154	        if (!windcaveToken) {
1155	          return res.status(400).json({ message: "windcaveToken is required when Windcave is configured" });
1156	        }
1157	
1158	        // Step 1: Create an attended session on Windcave using the pending transaction price
1159	        const sessionResult = await createAttendedSession(chargeAmount.toFixed(2), merchantRef);
1160	        if (!sessionResult.success || !sessionResult.sessionId) {
1161	          return res.status(502).json({ message: `Failed to create attended session: ${sessionResult.error}` });
1162	        }
1163	
1164	        // Step 2: Submit the NFC token captured by the iOS SDK against the session
1165	        paymentResult = await submitTapToPayToken(sessionResult.sessionId, windcaveToken);
1166	
1167	        // A false `success` means a processor/network error — not a card decline.
1168	        // Return upstream error without persisting any transaction outcome.
1169	        if (!paymentResult.success) {
1170	          return res.status(502).json({ message: `Payment processor error: ${paymentResult.error}` });
1171	        }
1172	      } else {
1173	        // Dev/staging environment — no real credentials configured
1174	        paymentResult = simulateAttendedTapToPay(merchantRef);
1175	      }
1176	
1177	      const finalStatus = paymentResult.approved ? "completed" : "failed";
1178	
1179	      let transaction;
1180	      if (pendingTransaction) {
1181	        // Finalize the existing pending transaction in place.
1182	        // The stored price is unchanged — it was the source of truth for chargeAmount.
1183	        transaction = await storage.updateTransactionStatus(
1184	          pendingTransaction.id,
1185	          finalStatus,
1186	          paymentResult.windcaveTransactionId ?? undefined
1187	        );
1188	        await storage.updateTransactionPaymentMethod(pendingTransaction.id, "tap_to_pay");
1189	        transaction = transaction ?? pendingTransaction;
1190	      } else {
1191	        // No pending transaction exists — create a fresh record using the exact charged amount.
1192	        // windcaveTransactionId is not part of the insert type (omitted from schema); set it
1193	        // via updateTransactionStatus after creation so the type contract is preserved.
1194	        transaction = await storage.createTransaction({
1195	          merchantId: mid,
1196	          itemName: "Tap to Pay Sale",
1197	          price: chargeAmount.toFixed(2),
1198	          status: finalStatus,
1199	          paymentMethod: "tap_to_pay",
1200	          splitEnabled: false,
1201	        });
1202	        if (paymentResult.windcaveTransactionId) {
1203	          const updated = await storage.updateTransactionStatus(
1204	            transaction.id,
1205	            finalStatus,
1206	            paymentResult.windcaveTransactionId
1207	          );
1208	          transaction = updated ?? transaction;
1209	        }
1210	      }
1211	
1212	      if (paymentResult.approved) {
1213	        broadcastToStone(transaction!.merchantId!, transaction!.taptStoneId, {
1214	          type: "transaction_updated",
1215	          transaction: { ...transaction, paymentMethod: "tap_to_pay" },
1216	        });
1217	        sendPushToMerchant(transaction!.merchantId!, "completed", transaction!.itemName, transaction!.price, transaction!.id).catch(() => {});
1218	      }
1219	
1220	      res.json({ approved: paymentResult.approved ?? false, transactionId: transaction!.id });
1221	    } catch (error) {
1222	      console.error("Tap to Pay error:", error);
1223	      res.status(500).json({ message: "Tap to Pay processing failed" });
1224	    }
1225	  });
